#ifndef HAIKU_ICONS_HPP
#define HAIKU_ICONS_HPP

#include <cstddef>
#include <cstdint>

typedef struct haiku_icon_t {
    const char    *name; /* file name without .ico; nullptr ends the table */
    const uint8_t *data;
    size_t         size;
} haiku_icon_t;

extern const haiku_icon_t haiku_icons[];

class BBitmap;

/* The 16x16 image of an icon compiled into the binary, decoded once and
   kept; nullptr if there is no such icon. Any thread. */
BBitmap *haiku_icon(const char *name);

#endif
